SRA_CATEGORIES = [
    'Conduct',
    'Costs information deficient',
    'Costs excessive',
    'Criminal activity',
    'Data protection / breach of confidentiality',
    'Delay',
    'Discrimination',
    'Failure to advise',
    'Failure to comply with agreed remedy',
    'Failure to follow instructions',
    'Failure to investigate complaint internally',
    'Failure to keep informed',
    'Failure to keep papers safe',
    'Failure to progress',
    'Other',
]


def seed_categories(apps, schema_editor):
    ComplaintCategory = apps.get_model('backend', 'ComplaintCategory')
    for order, name in enumerate(SRA_CATEGORIES, start=1):
        ComplaintCategory.objects.get_or_create(name=name, defaults={'sort_order': order})


def unseed_categories(apps, schema_editor):
    apps.get_model('backend', 'ComplaintCategory').objects.filter(
        name__in=SRA_CATEGORIES, complaints__isnull=True).delete()


